import { useEffect, useState } from 'react';
import { Link, Navigate, Route, Routes, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { QRCodeSVG } from 'qrcode.react';
import { ArrowLeft, BadgeCheck, BarChart3, Bell, CakeSlice, Check, CheckCircle2, ChevronRight, Copy, ExternalLink, Gift, Heart, LockKeyhole, MapPinned, Minus, Plus, ReceiptText, Settings, Share2, ShoppingBag, Store, Truck, UserRound, Users, WalletCards } from 'lucide-react';
import { AppShell } from './components/AppShell';
import { PremiumClient, PremiumPreview, PremiumStaff } from './PremiumPreview';
import { LoyaltyCard } from './components/LoyaltyCard';
import { ADOCE_ASSETS } from './assets/adoceAssets';
import { QrScanButton } from './components/AdoceVisuals';
import { allPayments, DiscountReason, DiscountType, FlavorStock, noQrPayments, Payment, PlannedProduction, PromoCard, Reservation, Sale, SaleItem, SeasonalTheme, useStore } from './store';
import { adjustCustomerStamps, claimCloudSale, clearStaffToken, clearToken, createCloudSale, listCustomers, loginBetaCustomer, loginStaffBeta, registerBetaCustomer, updateBetaCustomer, type CustomerAdminRow } from './lib/betaApi';
import { ADOCE_PAYMENT_WHATSAPP, ADOCE_PIX_CITY, ADOCE_PIX_COPY_PASTE, ADOCE_PIX_RECEIVER, pixInstructions } from './pix';

const money=(v:number)=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
function Title({children}:{children:React.ReactNode}){return <div className="ornament-title"><span>❧</span><h2>{children}</h2><span>❧</span></div>}
function Logo(){return <span className="logo-frame"><img src={ADOCE_ASSETS.branding.logo} alt="Adoce Brigaderia"/></span>}
function Notice({children}:{children:React.ReactNode}){return <p className="inline-notice"><CheckCircle2/>{children}</p>}
const lgpdText='Aceito participar do Adoce Club e autorizo o uso dos meus dados para identificar compras, carimbos, premios e comunicacoes da Adoce Brigaderia. Posso pedir correcao ou exclusao dos meus dados pelo WhatsApp da empresa.';
const betaText='Estou participando da versão beta do Adoce Club. Entendo que o sistema ainda está em testes e pode apresentar erros ou ajustes durante a validação.';
const isPixManual=(payment:Payment)=>payment==='Pix';
const pixWhatsappText=(reservation:Reservation,total:number)=>`Olá, Adoce Brigaderia! Segue o comprovante da reserva ${reservation.id} no valor de ${money(total)}.`;
const discountReasons:DiscountReason[]=['Promoção','Aniversário','Cortesia parcial','Ajuste manual','Cupom/campanha'];
const isCardVisible=(card:PromoCard)=>card.active&&(!card.validUntil||new Date(card.validUntil)>=new Date());
const displayDate=(date:string)=>date?new Date(`${date}T12:00:00`).toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit'}):'Data a definir';
const saleItems=(sale:Sale):SaleItem[]=>sale.items?.length?sale.items:[{flavor:sale.flavor||'Fatia',quantity:sale.qty,syrup:sale.syrup}];
const saleItemsText=(sale:Sale)=>saleItems(sale).map(i=>`${i.quantity}x ${i.flavor}${i.syrup?` · Calda: ${i.syrup}`:''}`).join(' · ');
const soldByFlavor=(sales:Sale[],flavor:string)=>sales.reduce((total,sale)=>total+saleItems(sale).filter(item=>item.flavor===flavor).reduce((a,item)=>a+item.quantity,0),0);
const shortFlavor=(flavor:FlavorStock|string)=>{const name=typeof flavor==='string'?flavor:flavor.shortName||flavor.name;return name.length>22?`${name.slice(0,20).trim()}...`:name};
const uid=(prefix:string)=>`${prefix}${Date.now().toString(36).toUpperCase()}`;

function RequireClient({children}:{children:React.ReactNode}){const registered=useStore(s=>s.customer.registered);return registered?<>{children}</>:<Navigate to="/cadastro" replace/>}
function RequireStaff({children}:{children:React.ReactNode}){const ok=useStore(s=>s.staffAuthenticated);return ok?<>{children}</>:<Navigate to="/equipe" replace/>}
function CustomerRegister(){const nav=useNavigate();const sync=useStore(s=>s.syncCustomer);const [form,setForm]=useState({name:'',whatsapp:'',email:'',password:'',instagram:'',birthDate:'',inviteCode:'',lgpdAccepted:false,betaAccepted:false,acceptsPromotions:true});const [error,setError]=useState('');const [saving,setSaving]=useState(false);const update=(patch:Partial<typeof form>)=>setForm({...form,...patch});const submit=async()=>{if(!form.name.trim()||form.whatsapp.replace(/\D/g,'').length<10||form.password.length<4){setError('Informe nome, WhatsApp válido e uma senha com pelo menos 4 caracteres.');return}if(!form.lgpdAccepted||!form.betaAccepted){setError('Para participar do beta, aceite a LGPD e o aviso de testes.');return}setSaving(true);setError('');try{sync(await registerBetaCustomer({...form,registered:true}));nav('/cliente')}catch(e){setError(e instanceof Error?e.message:'Não consegui cadastrar agora.')}finally{setSaving(false)}};return <div className="login-screen register-screen"><Logo/><h1>Adoce Club</h1><p>Cadastro beta de fidelidade</p><div className="login-card"><label>Nome<input value={form.name} onChange={e=>update({name:e.target.value})} autoComplete="name"/></label><label>WhatsApp<input value={form.whatsapp} onChange={e=>update({whatsapp:e.target.value})} inputMode="tel" autoComplete="tel"/></label><label>Crie sua senha<input value={form.password} onChange={e=>update({password:e.target.value})} type="password" autoComplete="new-password"/></label><label>Código de convite opcional<input value={form.inviteCode} onChange={e=>update({inviteCode:e.target.value.toUpperCase()})} placeholder="Ex.: BEZERRA10"/></label><label>E-mail opcional<input value={form.email} onChange={e=>update({email:e.target.value})} type="email" autoComplete="email"/></label><label>Aniversário opcional<input value={form.birthDate} onChange={e=>update({birthDate:e.target.value})} type="date"/></label><label>Instagram opcional<input value={form.instagram} onChange={e=>update({instagram:e.target.value})}/></label><label className="check-line"><input type="checkbox" checked={form.lgpdAccepted} onChange={e=>update({lgpdAccepted:e.target.checked})}/><span>{lgpdText}</span></label><label className="check-line"><input type="checkbox" checked={form.betaAccepted} onChange={e=>update({betaAccepted:e.target.checked})}/><span>{betaText}</span></label><label className="check-line"><input type="checkbox" checked={form.acceptsPromotions} onChange={e=>update({acceptsPromotions:e.target.checked})}/><span>Aceito receber mensagens sobre benefícios e novidades do Adoce Club.</span></label>{error&&<Notice>{error}</Notice>}<button className="primary-button" disabled={saving} onClick={submit}><Heart/> {saving?'Criando...':'Criar meu Adoce Club'}</button><Link className="secondary-button" to="/entrar">Já tenho cadastro</Link></div><small>Beta controlado para clientes que aceitarem testar.</small></div>}
function CustomerLogin(){const nav=useNavigate();const sync=useStore(s=>s.syncCustomer);const [whatsapp,setWhatsapp]=useState('');const [password,setPassword]=useState('');const [error,setError]=useState('');const [saving,setSaving]=useState(false);const submit=async()=>{setSaving(true);setError('');try{sync(await loginBetaCustomer(whatsapp,password));nav('/cliente')}catch(e){setError(e instanceof Error?e.message:'WhatsApp ou senha não conferem.')}finally{setSaving(false)}};return <div className="login-screen"><Logo/><h1>Adoce Club</h1><p>Acesse seu cartão fidelidade</p><div className="login-card"><label>WhatsApp<input value={whatsapp} onChange={e=>setWhatsapp(e.target.value)} inputMode="tel" autoComplete="tel"/></label><label>Senha<input value={password} onChange={e=>setPassword(e.target.value)} type="password" autoComplete="current-password"/></label>{error&&<Notice>{error}</Notice>}<button className="primary-button" disabled={saving} onClick={submit}><LockKeyhole/> {saving?'Entrando...':'Entrar'}</button><Link className="secondary-button" to="/cadastro">Fazer cadastro beta</Link></div></div>}
function StaffLogin(){const nav=useNavigate();const loginStaff=useStore(s=>s.loginStaff);const [user,setUser]=useState<'rubens'|'beth'>('rubens');const [pin,setPin]=useState('');const [error,setError]=useState('');const [saving,setSaving]=useState(false);const submit=async()=>{setSaving(true);setError('');try{await loginStaffBeta(user,pin);loginStaff(user);nav(user==='beth'?'/vendedor':'/admin')}catch(e){setError(e instanceof Error?e.message:'PIN temporário inválido.')}finally{setSaving(false)}};return <div className="login-screen"><Logo/><h1>Adoce Club</h1><p>Acesso exclusivo da equipe</p><div className="login-card"><div className="choice-grid"><button className={user==='rubens'?'active':''} onClick={()=>setUser('rubens')}>Rubens</button><button className={user==='beth'?'active':''} onClick={()=>setUser('beth')}>Beth</button></div><label>PIN temporário<input value={pin} onChange={e=>setPin(e.target.value)} inputMode="numeric" type="password"/></label>{error&&<Notice>{error}</Notice>}<button className="primary-button" disabled={saving} onClick={submit}><Store/> {saving?'Validando...':'Entrar na operação'}</button><Link className="secondary-button" to="/cliente"><ArrowLeft/> Voltar ao cliente</Link></div><small>Este acesso não aparece para clientes.</small></div>}

function ClientHome(){const c=useStore(s=>s.company);const promoCards=useStore(s=>s.promoCards);const flavors=useStore(s=>s.cashFlavors);const allReservations=useStore(s=>s.reservations);const reservations=allReservations.slice(0,3);const mainCards=promoCards.filter(isCardVisible);return <AppShell><section className="soft-card reserve-card"><div><b>Hoje é dia de fatia!</b><span>Reserve a sua antes que acabe 💗</span></div><div className="reserve-actions"><Link to="/cliente/reserva">Reservar agora</Link><a href="#sabores">Ver sabores</a><Link to="/cliente/como-chegar">Como chegar</Link></div></section><LoyaltyCard compact/><QrScanButton/>{reservations.length?<section className="soft-card client-reservations"><Title>Suas reservas</Title>{reservations.map(r=><div key={r.id} className={`client-reservation ${r.status==='cancelled'?'cancelled':''}`}><b>{r.quantity} fatia(s) · {displayDate(r.date)}</b><span>{r.status}{r.cancelNote?` · ${r.cancelNote}`:''}</span><small>{(r.items??[{flavor:r.flavor,quantity:r.quantity,syrup:r.syrup}]).map(i=>`${i.quantity}x ${i.flavor}`).join(' · ')}</small></div>)}</section>:null}<div id="sabores"><Title>Sabores da Semana</Title>{mainCards.length?<div className="promo-card-grid">{mainCards.map(card=><Link className={`soft-card promo-card ${card.flash?'flash':''}`} to={`/cliente/reserva?dia=${card.date}`} key={card.id}><img src={card.imageUrl} alt={card.title}/><div><b>{card.flash?'Promoção relâmpago':card.title}</b><span>Disponível até {displayDate(card.date)}</span><small>{card.flavors.slice(0,3).map(f=>f.name).join(' · ')}</small></div><ChevronRight/></Link>)}</div>:null}<section className="soft-card flavor-card"><img src={ADOCE_ASSETS.stamps.alt} alt="Fatia de torta de chocolate"/><ul>{flavors.filter(f=>f.quantity>0).map(f=><li key={f.name}>{f.name}</li>)}</ul><div className="floating-heart">♡</div></section></div><div className="quick-panels"><Link className="soft-card quick-panel" to="/cliente/familia"><Users/><div><b>Cartão Familiar</b><span>Compartilhe seus carimbos</span></div><ChevronRight/></Link><Link className="soft-card quick-panel" to="/cliente/indicacoes"><Gift/><div><b>Indique Amigos</b><span>Ganhe benefícios</span></div><ChevronRight/></Link></div><section className="soft-card location-card"><MapPinned/><div><b>Venha buscar sua fatia</b><span>{c.placeName}</span></div><Link to="/cliente/como-chegar">Abrir rotas</Link></section></AppShell>}
function CardPage(){const allSales=useStore(s=>s.sales);const sales=allSales.filter(v=>v.claimed);return <AppShell><Link className="secondary-button back-link" to="/cliente"><ArrowLeft/> Voltar</Link><LoyaltyCard/><section className="soft-card history-card"><Title>Histórico recente</Title>{sales.length? sales.map(v=><p key={v.id}><Heart fill="currentColor"/> +{v.qty} carimbos <span>{v.kind}</span></p>):<p><Heart fill="currentColor"/> Seus carimbos pagos aparecem aqui.</p>}<p><Gift/> Indicações convertidas <span>bônus</span></p></section></AppShell>}

function FamilyPage(){const s=useStore();const [role,setRole]=useState('Mãe');const relations=['Pai','Mãe','Marido','Esposa','Filho','Filha','Namorado','Namorada','Cunhado','Cunhada','Genro','Nora','Neto','Neta'];const purchases=s.sales.filter(v=>v.claimed).length;const members=s.family?.members.length?s.family.members:[s.customer.name||'Você','Família'];return <AppShell><section className="soft-card family-panel family-doce-panel"><Title>Família Doce</Title><p className="center-copy">Todos os membros compartilham os carimbos <Heart size={14} fill="currentColor"/></p><div className="family-people">{members.map((member,index)=><div key={`${member}-${index}`}><span>{member.slice(0,2)}</span><b>{member}</b><small>{index===0?role:'Convidado'} · {index===0?purchases:0} compra(s)</small></div>)}</div><div className="relation-grid">{relations.map(item=><button className={role===item?'active':''} key={item} onClick={()=>setRole(item)}>{item}</button>)}</div>{s.family?<><LoyaltyCard compact family/><button className="invite-code" onClick={()=>navigator.clipboard?.writeText(s.family!.code)}>{s.family.code}<Copy/></button></>:<button className="primary-button" onClick={s.createFamily}>Criar cartão familiar</button>}</section></AppShell>}
function ReferralPage(){const s=useStore();const [msg,setMsg]=useState('');return <AppShell><section className="soft-card referral-panel"><Title>Indique Amigos</Title><p>Convide amigos e ganhe benefícios deliciosos!</p><label>Seu código de convite</label><button className="invite-code" onClick={()=>navigator.clipboard?.writeText(s.referralCode)}>{s.referralCode}<Copy/></button><button className="primary-button share-button" onClick={()=>window.open(`https://wa.me/?text=${encodeURIComponent('Use meu código '+s.referralCode)}`)}><Share2/> Compartilhar convite</button><small>O amigo usa este código no campo “Código de convite opcional” do cadastro beta. Quando fizer a 1ª compra, você ganha +1 carimbo.</small><button className="secondary-button" onClick={()=>{s.convertReferral();setMsg('Indicação convertida e bônus liberado.')}}>Simular primeira compra paga</button>{msg&&<Notice>{msg}</Notice>}</section><section className="soft-card ranking"><Title>Ranking de indicações</Title>{s.referrals.map(r=><p key={r.customer}><b>{r.customer}</b><span>{r.converted} convertidas · +{r.bonus} carimbos</span></p>)}</section></AppShell>}
function Awards(){const s=useStore();return <AppShell><section className="soft-card"><Title>Meus Prêmios</Title>{s.rewards.length?s.rewards.map(r=><div className="award-row" key={r.id}><Gift/><div><b>{r.type}</b><span>{r.origin} · {r.status}</span></div></div>):<p className="empty-copy">Complete a cartela para ganhar uma fatia grátis.</p>}</section><section className="soft-card"><Title>Meus Selos</Title><div className="badge-grid">{s.badges.map(b=><div className={b.earned?'earned':''} key={b.id}><BadgeCheck/><b>{b.name}</b><small>{b.reason}</small></div>)}</div></section></AppShell>}
function Profile(){const s=useStore();const [p,setP]=useState(s.customer);const [ok,setOk]=useState(false);const [error,setError]=useState('');const save=async()=>{setError('');try{const data=await updateBetaCustomer(p);s.syncCustomer(data);setOk(true)}catch(e){setError(e instanceof Error?e.message:'Não consegui salvar perfil.')}};return <AppShell><section className="soft-card config-card"><Title>Meu Perfil</Title>{(['name','whatsapp','email','instagram','birthDate'] as const).map(k=><label key={k}>{({name:'Nome',whatsapp:'WhatsApp',email:'E-mail',instagram:'Instagram',birthDate:'Data de nascimento'} as const)[k]}<input type={k==='birthDate'?'date':k==='email'?'email':'text'} value={p[k]} onChange={e=>setP({...p,[k]:e.target.value})}/></label>)}<label className="check-line"><input type="checkbox" checked={p.acceptsPromotions} onChange={e=>setP({...p,acceptsPromotions:e.target.checked})}/> Aceito receber promoções</label><button className="primary-button" onClick={save}>Salvar perfil</button>{ok&&<Notice>Perfil salvo.</Notice>}{error&&<Notice>{error}</Notice>}</section></AppShell>}
function ClientMore(){return <AppShell><section className="soft-card admin-menu"><Link to="/cliente/perfil"><UserRound/>Meu Perfil<ChevronRight/></Link><Link to="/cliente/premios"><Gift/>Meus Prêmios e Selos<ChevronRight/></Link><Link to="/cliente/indicacoes"><Users/>Minhas Indicações<ChevronRight/></Link><Link to="/cliente/como-chegar"><MapPinned/>Como chegar<ChevronRight/></Link><Link to="/entrar" onClick={clearToken}><ExternalLink/>Sair<ChevronRight/></Link></section></AppShell>}

function ReservationPage(){const s=useStore();const [params]=useSearchParams();const visibleCards=s.promoCards.filter(isCardVisible);const planDates=[...new Set([...visibleCards.map(c=>c.date),...s.plannedProductions.map(p=>p.date)])].filter(Boolean);const [date,setDate]=useState(params.get('dia')||planDates[0]||new Date().toISOString().slice(0,10));const plan=s.plannedProductions.find(p=>p.date===date);const card=visibleCards.find(c=>c.date===date);const availableFlavors=(plan?.flavors.length?plan.flavors:card?.flavors.length?card.flavors:s.cashFlavors).filter(f=>f.quantity>0);const syrups=plan?.syrups.length?plan.syrups:card?.syrups.length?card.syrups:s.syrups;const [qty,setQty]=useState(1);const [flavor,setFlavor]=useState(availableFlavors[0]?.name??'Ninho com Morango');const [syrup,setSyrup]=useState(syrups[0]??'');const [type,setType]=useState<'Presencial'|'Delivery / Retirada'>('Presencial');const [payNow,setPayNow]=useState(true);const [payment,setPayment]=useState<Payment>('Pix');const [cart,setCart]=useState<{flavor:string;quantity:number;syrup?:string}[]>([]);const [created,setCreated]=useState<Reservation|null>(null);const [copied,setCopied]=useState(false);const currentFlavor=availableFlavors.some(f=>f.name===flavor)?flavor:availableFlavors[0]?.name??flavor;const currentSyrup=syrups.includes(syrup)?syrup:syrups[0]??syrup;const cartQty=cart.reduce((a,v)=>a+v.quantity,0);const cartSummary=cart.map(v=>`${v.quantity}x ${v.flavor}`).join(' · ');const addItem=()=>{if(qty<1||!currentFlavor)return;setCart(list=>{const index=list.findIndex(v=>v.flavor===currentFlavor&&v.syrup===(payNow?currentSyrup:undefined));if(index>=0)return list.map((item,i)=>i===index?{...item,quantity:item.quantity+qty}:item);return [...list,{flavor:currentFlavor,quantity:qty,syrup:payNow?currentSyrup:undefined}]});setQty(1)};const updateItem=(index:number,delta:number)=>setCart(list=>list.map((item,i)=>i===index?{...item,quantity:item.quantity+delta}:item).filter(item=>item.quantity>0));const confirm=()=>{const items=cart.length?cart:[{flavor:currentFlavor,quantity:qty,syrup:payNow?currentSyrup:undefined}];const total=items.reduce((a,v)=>a+v.quantity,0);setCreated(s.addReservation({customer:s.customer.name||s.customer.whatsapp,quantity:total,flavor:items.map(v=>v.flavor).join(' + '),items,date,syrup:items.length===1?items[0].syrup:undefined,deliveryType:type,status:payNow?'waiting_payment':'requested',paymentMethod:payNow?payment:'Dinheiro',payNow,paymentLinkUrl:payNow&&payment==='Mercado Pago Link'?'https://mpago.la/reserva-demo':undefined,pixCode:payNow&&isPixManual(payment)?ADOCE_PIX_COPY_PASTE:undefined,notes:card?.title??''}))};if(created)return <AppShell><section className="soft-card qr-card reservation-created"><div className="success-medal"><Check/></div><Title>Reserva criada!</Title><p>{created.quantity} fatia(s)</p><div className="reservation-created-list">{(created.items??[{flavor:created.flavor,quantity:created.quantity,syrup:created.syrup}]).map((item,i)=><span key={`${item.flavor}-${i}`}>{item.quantity}x {item.flavor}{item.syrup?` · Calda: ${item.syrup}`:''}</span>)}</div><div className="token-box">{displayDate(created.date)}<br/>Status: {created.status}<br/>{created.payNow?'Pagamento antecipado':'Pagamento na retirada'}</div>{created.pixCode&&<div className="pix-payment-box"><QRCodeSVG value={created.pixCode} size={190} fgColor="#5b211c"/><p>{pixInstructions}</p><small>Recebedor: {ADOCE_PIX_RECEIVER}<br/>Cidade: {ADOCE_PIX_CITY}</small><div className="token-box">{created.pixCode}</div><button className="primary-button" onClick={()=>{navigator.clipboard?.writeText(created.pixCode!);setCopied(true)}}>Copiar código Pix</button><button className="secondary-button" onClick={()=>window.open(`https://wa.me/${ADOCE_PAYMENT_WHATSAPP}?text=${encodeURIComponent(pixWhatsappText(created,created.quantity*s.settings.price))}`)}>Enviar comprovante pelo WhatsApp</button></div>}{created.paymentLinkUrl&&<><button className="primary-button" onClick={()=>{navigator.clipboard?.writeText(created.paymentLinkUrl!);setCopied(true)}}>Copiar link de pagamento</button><button className="secondary-button" onClick={()=>window.open(`https://wa.me/?text=${encodeURIComponent(created.paymentLinkUrl!)}`)}>Enviar pelo WhatsApp</button></>}{copied&&<Notice>{created.pixCode?'Código Pix copiado.':'Link de pagamento copiado.'}</Notice>}<small className="reservation-footnote">Se houver problema de produção, combinaremos troca, crédito ou devolução pelo WhatsApp.</small></section></AppShell>;return <AppShell><section className="soft-card config-card reservation-builder"><Title>Montar sua reserva</Title>{card&&<img className="reservation-card-image" src={card.imageUrl} alt={card.title}/>}<label>Dia da retirada<select value={date} onChange={e=>setDate(e.target.value)}>{planDates.map(d=><option key={d} value={d}>{displayDate(d)}</option>)}</select></label>{availableFlavors.length?<div className="flavor-preview-list">{availableFlavors.map(f=><span key={f.name}>{f.name}</span>)}</div>:null}<div className="cart-picker"><label>Quantidade<input type="number" min="1" value={qty} onChange={e=>setQty(Math.max(1,+e.target.value||1))}/></label><label>Sabor<select value={currentFlavor} onChange={e=>setFlavor(e.target.value)}>{availableFlavors.map(f=><option key={f.name}>{f.name}</option>)}</select></label>{payNow&&<label>Calda<select value={currentSyrup} onChange={e=>setSyrup(e.target.value)}>{syrups.map(v=><option key={v}>{v}</option>)}</select></label>}<button className="secondary-button" type="button" onClick={addItem}><Plus/> Adicionar à cestinha</button></div><section className="reservation-cart"><h3>Sua cestinha</h3>{cart.length?cart.map((item,index)=><div className="cart-item" key={`${item.flavor}-${index}`}><div><b>{item.flavor}</b><span>{item.syrup?`Calda: ${item.syrup}`:'Calda será escolhida depois'}</span></div><button type="button" onClick={()=>updateItem(index,-1)}><Minus/></button><strong>{item.quantity}</strong><button type="button" onClick={()=>updateItem(index,1)}><Plus/></button></div>):<p>{qty}x {currentFlavor} pronta para adicionar.</p>}<b>Total: {cartQty||qty} fatia(s)</b>{cartSummary&&<small>{cartSummary}</small>}</section><div className="choice-grid"><button className={type==='Presencial'?'active':''} onClick={()=>setType('Presencial')}>Retirada</button><button className={type!=='Presencial'?'active':''} onClick={()=>setType('Delivery / Retirada')}>Delivery</button></div><div className="choice-grid"><button className={payNow?'active':''} onClick={()=>setPayNow(true)}>Pagar agora</button><button className={!payNow?'active':''} onClick={()=>setPayNow(false)}>Pagar na retirada</button></div>{payNow&&<label>Pagamento<select value={payment} onChange={e=>setPayment(e.target.value as Payment)}><option>Pix</option><option>Mercado Pago Link</option><option>Cartão</option></select></label>}<Notice>O pagamento antecipado garante a reserva. Se algum sabor não ficar pronto, vocês poderão escolher troca, crédito ou devolução.</Notice><button className="primary-button" onClick={confirm}>Confirmar reserva</button></section></AppShell>}
function LocationPage(){const c=useStore(s=>s.company);const query=c.placeName||'Festival de fatias Adoce Brigaderia';const maps=c.mapsUrl||`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;const waze=c.wazeUrl||`https://waze.com/ul?q=${encodeURIComponent(query)}&navigate=yes`;const uber=c.uberUrl||`https://m.uber.com/ul/?action=setPickup&dropoff[formatted_address]=${encodeURIComponent(query)}`;return <AppShell><section className="soft-card location-page"><MapPinned/><Title>Venha buscar sua fatia</Title><p>Procure por <b>{query}</b> no app de rotas.</p><address>{c.address||query}{c.city||c.state?<><br/>{[c.city,c.state].filter(Boolean).join(' / ')}</>:null}</address><a className="primary-button" href={waze} target="_blank">Abrir no Waze</a><a className="secondary-button" href={maps} target="_blank">Abrir no Google Maps</a><a className="secondary-button" href={uber} target="_blank">Chamar Uber</a><button className="text-button" onClick={()=>navigator.clipboard?.writeText(query)}>Copiar nome do local</button></section></AppShell>}
function Redeem(){const {token=''}=useParams();const sync=useStore(s=>s.syncCustomer);const [status,setStatus]=useState('');const [saving,setSaving]=useState(false);const redeem=async()=>{setSaving(true);setStatus('');try{const data=await claimCloudSale(token);sync(data);setStatus(data.rewards?.length?'Parabéns! Cartela completa: sua fatia grátis ficou em Meus Prêmios.':'Carimbos adicionados com sucesso!')}catch(e){setStatus(e instanceof Error?e.message:'Este token é inválido, pendente ou já foi usado.')}finally{setSaving(false)}};return <AppShell><section className="soft-card redeem-card"><div className="success-medal"><Check/></div><Title>Resgatar carimbos</Title><div className="token-box">{token}</div><button className="primary-button" disabled={saving} onClick={redeem}>{saving?'Validando...':'Receber carimbos'}</button>{status&&<Notice>{status}</Notice>}<Link className="secondary-button" to="/cliente/premios">Ver meus prêmios</Link></section></AppShell>}

function SaleResult({sale,onReset}:{sale:Sale;onReset:()=>void}){const update=useStore(s=>s.updatePayment);const replaceToken=useStore(s=>s.replaceSaleToken);const [current,setCurrent]=useState(sale);const [error,setError]=useState('');const detail=saleItemsText(current);const setStatus=async(status:Sale['status'])=>{setError('');const v=update(sale.id,status);if(!v)return;if(status==='paid'){try{const cloud=await createCloudSale(v);replaceToken(v.id,cloud.token);setCurrent({...v,token:cloud.token})}catch(e){setError(e instanceof Error?e.message:'Não consegui liberar QR na nuvem.');setCurrent(v)}}else setCurrent(v)};if(['declined','cancelled','expired'].includes(current.status)&&!noQrPayments.includes(current.payment))return <section className="soft-card qr-card"><div className="success-medal waiting"><WalletCards/></div><Title>{current.status==='declined'?'Pagamento recusado':current.status==='cancelled'?'Cobrança cancelada':'Cobrança expirada'}</Title><div className="token-box">Esta venda não gerou QR nem carimbo.</div><p>{current.qty} fatia(s) · {current.payment}</p>{detail&&<small>{detail}</small>}<button className="primary-button" onClick={onReset}>Nova venda</button></section>;if(current.status!=='paid'&&!noQrPayments.includes(current.payment))return <section className="soft-card qr-card"><div className="success-medal waiting"><WalletCards/></div><Title>Aguardando pagamento</Title><p>{current.payment} · {current.terminal}</p>{detail&&<small>{detail}</small>}{current.paymentLinkUrl&&<div className="token-box">{current.paymentLinkUrl}</div>}<p>Enquanto pendente, não gera QR nem carimbo.</p><button className="primary-button" onClick={()=>setStatus('paid')}>Pagamento aprovado</button><button className="secondary-button" onClick={()=>setStatus('declined')}>Pagamento recusado</button><button className="text-button" onClick={()=>setStatus('cancelled')}>Cancelar cobrança</button>{error&&<Notice>{error}</Notice>}</section>;if(noQrPayments.includes(current.payment))return <section className="soft-card qr-card"><div className="success-medal"><Check/></div><Title>Saída registrada!</Title><div className="token-box">Esta operação não gera QR nem carimbo.</div><p>{current.qty} fatia(s) · {current.payment}</p>{detail&&<small>{detail}</small>}<p>Operador: {current.seller}<br/>{current.createdAt}</p><button className="primary-button" onClick={onReset}>Nova operação</button></section>;const link=`${location.origin}/cliente/resgatar/${current.token}`;return <section className="soft-card qr-card"><div className="success-medal"><Check/></div><Title>Venda registrada!</Title><p>{current.qty} fatias · {money(current.grossAmount)} · {current.payment}</p>{detail&&<small>{detail}</small>}{current.kind==='Presencial'?<><div className="qr-frame"><QRCodeSVG value={link} size={205} fgColor="#5b211c"/></div><p>Peça ao cliente para escanear</p></>:<><div className="token-box">{link}</div><button className="secondary-button" onClick={()=>navigator.clipboard?.writeText(link)}><Copy/> Copiar link</button></>}<button className="primary-button" onClick={onReset}>Nova venda</button></section>}
function SalePanel(){const s=useStore();const availableFlavors=s.cashFlavors.filter(f=>f.quantity>0);const [qty,setQty]=useState(3);const [flavor,setFlavor]=useState(availableFlavors[0]?.name??'');const [syrup,setSyrup]=useState(s.syrups[0]??'');const [cart,setCart]=useState<SaleItem[]>([]);const [payment,setPayment]=useState<Payment>('Pix');const [discountType,setDiscountType]=useState<DiscountType>('none');const [discountValue,setDiscountValue]=useState(0);const [discountReason,setDiscountReason]=useState<DiscountReason>('Promoção');const [discountNote,setDiscountNote]=useState('');const [notes,setNotes]=useState('');const [sale,setSale]=useState<Sale|null>(null);const [saving,setSaving]=useState(false);const [error,setError]=useState('');const user=s.users.find(u=>u.id===s.currentUserId);const terminal=s.terminals.find(t=>t.id===user?.defaultTerminalId);const selectedFlavor=availableFlavors.some(f=>f.name===flavor)?flavor:availableFlavors[0]?.name??flavor;const selectedSyrup=s.syrups.includes(syrup)?syrup:s.syrups[0]??syrup;const currentItems=cart.length?cart:[{flavor:selectedFlavor,quantity:qty,syrup:selectedSyrup}];const totalQty=currentItems.reduce((a,v)=>a+v.quantity,0);const subtotal=noQrPayments.includes(payment)?0:totalQty*s.settings.price;const discountAmount=Math.min(subtotal,Math.max(0,discountType==='percent'?subtotal*(discountValue/100):discountType==='amount'?discountValue:0));const total=Math.max(0,subtotal-discountAmount);const addItem=()=>{if(!selectedFlavor||qty<1)return;setCart(list=>{const index=list.findIndex(item=>item.flavor===selectedFlavor&&item.syrup===selectedSyrup);if(index>=0)return list.map((item,i)=>i===index?{...item,quantity:item.quantity+qty}:item);return [...list,{flavor:selectedFlavor,quantity:qty,syrup:selectedSyrup}]});setQty(1)};const updateItem=(index:number,delta:number)=>setCart(list=>list.map((item,i)=>i===index?{...item,quantity:item.quantity+delta}:item).filter(item=>item.quantity>0));const submit=async(kind:Sale['kind'])=>{if(!currentItems.length||totalQty<1){setError('Adicione pelo menos uma fatia na venda.');return}if(noQrPayments.includes(payment)&&notes.trim().length<4){setError('Informe o motivo da cortesia, permuta ou fidelidade.');return}if(discountType!=='none'&&discountNote.trim().length<4){setError('Informe a observação do desconto.');return}setSaving(true);setError('');try{const local=s.addSale({qty:totalQty,items:currentItems,payment,kind,notes,discountType,discountValue,discountReason:discountType==='none'?undefined:discountReason,discountNote:discountType==='none'?undefined:discountNote});if(local.generatesStamps){const cloud=await createCloudSale(local);s.replaceSaleToken(local.id,cloud.token);setSale({...local,token:cloud.token})}else setSale(local)}catch(e){setError(e instanceof Error?e.message:'Não consegui registrar venda na nuvem.')}finally{setSaving(false)}};if(!s.cashOpen)return <section className="soft-card closed-sale"><Store/><h2>Abra o caixa antes da primeira venda</h2><Link className="primary-button" to="/admin/caixa">Abrir caixa agora</Link></section>;if(sale)return <SaleResult sale={sale} onReset={()=>{setSale(null);setCart([]);setQty(3)}}/>;return <section className="soft-card sale-panel"><Title>Nova venda</Title><div className="operator-line"><span>Operador: <b>{user?.name}</b></span><span>Terminal: <b>{terminal?.name??'Não configurado'}</b></span></div><label>Sabor da fatia<select value={selectedFlavor} onChange={e=>setFlavor(e.target.value)}>{availableFlavors.map(f=><option key={f.name}>{f.name}</option>)}</select></label><label>Calda disponível<select value={selectedSyrup} onChange={e=>setSyrup(e.target.value)}>{s.syrups.map(v=><option key={v}>{v}</option>)}</select></label><label>Quantidade de fatias</label><div className="quantity-row"><button aria-label="Diminuir quantidade" onClick={()=>setQty(Math.max(1,qty-1))}><Minus/></button><div>{qty}</div><button aria-label="Aumentar quantidade" onClick={()=>setQty(qty+1)}><Plus/></button><small>Valor unitário<br/><b>{money(s.settings.price)}</b></small></div><div className="quick-qty">{[1,2,3,4,6,10].map(v=><button className={v===qty?'active':''} key={v} onClick={()=>setQty(v)}>{v}</button>)}</div><button className="secondary-button sale-add-item" onClick={addItem}><ShoppingBag/> Adicionar à venda</button><div className="sale-cart-box"><b>Cestinha da venda</b>{cart.length?cart.map((item,index)=><div className="sale-cart-row" key={`${item.flavor}-${item.syrup}-${index}`}><span>{item.quantity}x {item.flavor}<small>{item.syrup?`Calda: ${item.syrup}`:'Sem calda'}</small></span><button aria-label={`Remover ${item.flavor}`} onClick={()=>updateItem(index,-1)}><Minus/></button><button aria-label={`Adicionar ${item.flavor}`} onClick={()=>updateItem(index,1)}><Plus/></button></div>):<small>Se não adicionar itens, a venda usa o sabor e quantidade selecionados acima.</small>}</div><div className="discount-box"><label>Desconto<select value={discountType} onChange={e=>setDiscountType(e.target.value as DiscountType)}><option value="none">Sem desconto</option><option value="amount">Valor em R$</option><option value="percent">Percentual %</option></select></label>{discountType!=='none'&&<><label>Valor do desconto<input type="number" min="0" value={discountValue} onChange={e=>setDiscountValue(+e.target.value)}/></label><label>Motivo<select value={discountReason} onChange={e=>setDiscountReason(e.target.value as DiscountReason)}>{discountReasons.map(r=><option key={r}>{r}</option>)}</select></label><label>Observação do desconto<input value={discountNote} onChange={e=>setDiscountNote(e.target.value)} placeholder="Ex.: balão 10%, idade, cupom"/></label></>}</div><div className="sale-total sale-total-stack"><span>{totalQty} fatia(s) na venda</span><span>Subtotal: {money(subtotal)}</span>{discountAmount>0&&<span>Desconto: -{money(discountAmount)}</span>}<b>Total: {noQrPayments.includes(payment)?'Sem receita':money(total)}</b><small>Carimbos continuam pela quantidade de fatias pagas.</small></div><div className="payment-grid">{allPayments.map(p=><button key={p} className={p===payment?'active':''} onClick={()=>setPayment(p)}><WalletCards/>{p}</button>)}</div>{(noQrPayments.includes(payment)||payment.includes('Mercado Pago'))&&<label>Observação<input value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Motivo ou referência da operação"/></label>}{error&&<Notice>{error}</Notice>}<div className="sale-types"><button disabled={saving} onClick={()=>submit('Presencial')}><Users/><b>{saving?'Registrando...':'Cliente Presencial'}</b><small>Consumir agora</small></button><button disabled={saving} onClick={()=>submit('Delivery / Retirada')}><Truck/><b>Delivery / Retirada</b><small>Entregar ou retirar</small></button></div></section>}
function RecentSales(){const sales=useStore(s=>s.sales);return <section className="soft-card recent-card"><Title>Vendas recentes</Title>{sales.length?sales.map(v=><div className="sale-row" key={v.id}><span className="sale-avatar">{v.seller.slice(0,2)}</span><div><b>{saleItems(v)[0]?.flavor??v.seller}</b><small>{v.qty} fatias · {v.kind} · {saleItems(v).length>1?'vários sabores':saleItems(v)[0]?.syrup??'sem calda'}</small></div><div><b>{v.grossAmount?money(v.grossAmount):'Sem receita'}</b><small>{v.payment} · {v.status}</small></div>{v.generatesQr?<Link to={`/vendedor/venda/${v.id}`}><ChevronRight/></Link>:<span>Sem QR</span>}</div>):<p>Nenhuma venda nesta demonstração.</p>}</section>}
function SellerHome(){const s=useStore();const paid=s.sales.filter(v=>v.status==='paid');const sold=s.sales.filter(v=>v.status!=='cancelled'&&v.status!=='declined').reduce((a,v)=>a+v.qty,0);return <AppShell role={s.role==='vendedor'?'vendedor':'admin'}><section className="soft-card cash-status"><Store/><div><b>{s.cashOpen?'Caixa aberto':'Caixa fechado'}</b><span>Festival do dia</span></div><Link to="/admin/caixa">{s.cashOpen?'Ver caixa':'Abrir caixa'}</Link></section><div className="metrics-grid"><div className="metric-card"><span>Fatias vendidas hoje</span><CakeSlice/><b>{sold}</b></div><div className="metric-card"><span>Total do dia</span><Heart/><b>{money(paid.reduce((a,v)=>a+v.grossAmount,0))}</b></div><div className="metric-card"><span>Restantes</span><Truck/><b>{Math.max(0,s.available-sold)}</b></div></div><SalePanel/><RecentSales/></AppShell>}
function SaleRoute(){const {id}=useParams();const sale=useStore(s=>s.sales.find(v=>v.id===id));return <AppShell role="vendedor">{sale?<SaleResult sale={sale} onReset={()=>history.back()}/>:<p>Venda não encontrada.</p>}</AppShell>}

function Cash(){const s=useStore();const todayIso=new Date().toISOString().slice(0,10);const todayPlan=s.plannedProductions.find(p=>p.date===todayIso)||s.plannedProductions[0];const plannedFlavors=todayPlan?.flavors.length?todayPlan.flavors:s.cashFlavors;const plannedSyrups=todayPlan?.syrups.length?todayPlan.syrups:s.syrups;const [fund,setFund]=useState(s.cashFund||100);const [flavors,setFlavors]=useState<FlavorStock[]>(s.cashOpen?s.cashFlavors:plannedFlavors);const [syrups,setSyrups]=useState((s.cashOpen?s.syrups:plannedSyrups).join(', '));const available=flavors.reduce((a,v)=>a+(Number(v.quantity)||0),0);const [pies,setPies]=useState(s.producedPies||Math.max(1,Math.ceil(plannedFlavors.reduce((a,v)=>a+v.quantity,0)/12)));const activeReservations=s.reservations.filter(r=>!['picked_up','cancelled','expired','refunded'].includes(r.status));const updateFlavor=(index:number,patch:Partial<FlavorStock>)=>setFlavors(list=>list.map((item,i)=>i===index?{...item,...patch}:item));const applyPlan=(plan?:PlannedProduction)=>{if(!plan)return;setFlavors(plan.flavors);setSyrups(plan.syrups.join(', '));setPies(Math.max(1,Math.ceil(plan.flavors.reduce((a,v)=>a+v.quantity,0)/12)));};return <AppShell role="admin"><section className="soft-card config-card"><Title>{s.cashOpen?'Caixa do Festival':'Abrir Caixa do Festival'}</Title><label>Data<input value={new Date().toLocaleDateString('pt-BR')} disabled/></label><label>Operador<input value={s.users.find(u=>u.id===s.currentUserId)?.name} disabled/></label>{todayPlan&&<button className="secondary-button" type="button" onClick={()=>applyPlan(todayPlan)}><CakeSlice/> Usar planejamento de {displayDate(todayPlan.date)}</button>}{activeReservations.length?<div className="token-box">Reservas online ativas: {activeReservations.length}<br/>{activeReservations.slice(0,3).map(r=>`${r.customer}: ${r.quantity} fatia(s)`).join(' · ')}</div>:<Notice>Nenhuma reserva online ativa neste aparelho.</Notice>}<label>Fundo fixo<input type="number" value={fund} onChange={e=>setFund(+e.target.value)}/></label><label>Tortas produzidas<input type="number" value={pies} onChange={e=>setPies(+e.target.value)}/></label><div className="form-divider">Sabores e fatias disponíveis</div>{flavors.map((item,index)=><div className="flavor-stock-row" key={index}><input aria-label={`Sabor ${index+1}`} value={item.name} onChange={e=>updateFlavor(index,{name:e.target.value})}/><input aria-label={`Quantidade ${index+1}`} type="number" min="0" value={item.quantity} onChange={e=>updateFlavor(index,{quantity:+e.target.value})}/></div>)}<button className="secondary-button" type="button" onClick={()=>setFlavors([...flavors,{name:'',quantity:0}])}><Plus/> Adicionar sabor</button><label>Caldas disponíveis<input value={syrups} onChange={e=>setSyrups(e.target.value)} placeholder="Leite Ninho, Brigadeiro, Doce de Leite"/></label><div className="token-box">Total inicial: {available} fatias</div><button className="primary-button" onClick={()=>s.openCash(fund,available,pies,flavors,syrups.split(','))}>{s.cashOpen?'Atualizar caixa':'Abrir caixa agora'}</button>{s.cashOpen&&<button className="secondary-button" onClick={s.closeCash}>Fechar caixa</button>}</section><ExpenseForm/><ClosingSummary/></AppShell>}
function ExpenseForm(){const add=useStore(s=>s.addExpense);const [amount,setAmount]=useState(0);const [category,setCategory]=useState<'Custo c/ lanche'|'Custo c/ insumos'>('Custo c/ lanche');const [description,setDescription]=useState('');const [ok,setOk]=useState(false);return <section id="gastos" className="soft-card config-card"><Title>Registrar gasto</Title><p>Use quando retirar dinheiro do caixa durante o festival.</p><label>Valor<input type="number" value={amount} onChange={e=>setAmount(+e.target.value)}/></label><div className="choice-grid"><button className={category.includes('lanche')?'active':''} onClick={()=>setCategory('Custo c/ lanche')}>Custo c/ lanche</button><button className={category.includes('insumos')?'active':''} onClick={()=>setCategory('Custo c/ insumos')}>Custo c/ insumos</button></div><label>Descrição<input value={description} onChange={e=>setDescription(e.target.value)}/></label><button className="primary-button" disabled={amount<=0} onClick={()=>{add({amount,category,description});setAmount(0);setOk(true)}}>Salvar gasto</button>{ok&&<Notice>Gasto registrado.</Notice>}</section>}
function ClosingSummary(){const s=useStore();const valid=s.sales.filter(v=>!['cancelled','declined','expired'].includes(v.status));const paid=valid.filter(v=>v.status==='paid');const slices=(p?:Payment)=>valid.filter(v=>!p||v.payment===p).reduce((a,v)=>a+v.qty,0);const subtotal=paid.reduce((a,v)=>a+(v.subtotalAmount??v.grossAmount),0);const discounts=paid.reduce((a,v)=>a+(v.discountAmount??0),0);const gross=paid.reduce((a,v)=>a+v.grossAmount,0);const fees=paid.reduce((a,v)=>a+v.feeAmount,0);const expenses=s.expenses.reduce((a,v)=>a+v.amount,0);return <section className="soft-card report-hero"><Title>Fechamento do Festival</Title><div className="report-grid"><div><span>Fatias iniciais</span><b>{s.available}</b></div><div><span>Fatias pagas</span><b>{paid.filter(v=>v.generatesStamps).reduce((a,v)=>a+v.qty,0)}</b></div><div><span>Cortesia</span><b>{slices('Cortesia')}</b></div><div><span>Permuta</span><b>{slices('Permuta')}</b></div><div><span>Fidelidade</span><b>{slices('Fidelidade')}</b></div><div><span>Restantes esperadas</span><b>{Math.max(0,s.available-slices())}</b></div><div><span>Subtotal antes descontos</span><b>{money(subtotal)}</b></div><div><span>Descontos</span><b>{money(discounts)}</b></div><div><span>Faturamento após descontos</span><b>{money(gross)}</b></div><div><span>Taxas</span><b>{money(fees)}</b></div><div><span>Valor líquido</span><b>{money(gross-fees)}</b></div><div><span>Gastos</span><b>{money(expenses)}</b></div><div><span>Dinheiro esperado</span><b>{money(s.cashFund+paid.filter(v=>v.payment==='Dinheiro').reduce((a,v)=>a+v.netAmount,0)-expenses)}</b></div></div><div className="form-divider">Sobras por sabor</div>{s.cashFlavors.map(f=>{const sold=soldByFlavor(valid,f.name);return <p className="flavor-leftover" key={f.name}><span>{f.name}</span><b>{Math.max(0,f.quantity-sold)} fatias</b></p>})}</section>}

function ReservationsAdmin(){const s=useStore();const [cancelId,setCancelId]=useState('');const [cancelNote,setCancelNote]=useState('');const active=s.reservations.filter(r=>!['picked_up','cancelled','expired','refunded'].includes(r.status));const cancel=()=>{if(!cancelId)return;s.updateReservation(cancelId,'cancelled',cancelNote||'Reserva cancelada pela equipe.');setCancelId('');setCancelNote('')};return <AppShell role="admin"><section className="soft-card reservations-admin"><Title>Reservas antecipadas</Title>{active.length?active.map(r=><div className="reservation-row reservation-row-wide" key={r.id}><div className="reservation-main"><b>{r.customer} · {r.quantity} fatia(s)</b><small>{displayDate(r.date)} · {r.paymentMethod} · {r.payNow?'pagamento antecipado':'pagar na retirada'} · {r.status}</small><div className="reservation-items">{(r.items??[{flavor:r.flavor,quantity:r.quantity,syrup:r.syrup}]).map((item,i)=><span key={`${r.id}-${i}`}>{item.quantity}x {item.flavor}{item.syrup?` · Calda: ${item.syrup}`:''}</span>)}</div></div><div className="reservation-actions"><button onClick={()=>s.updateReservation(r.id,'paid')}>Pago</button><button onClick={()=>s.updateReservation(r.id,'separating')}>Separar</button><button onClick={()=>s.updateReservation(r.id,'waiting_pickup')}>Aguardar retirada</button><button onClick={()=>s.updateReservation(r.id,'picked_up')}>Finalizar retirada</button><button onClick={()=>s.updateReservation(r.id,'credit','Oferecemos crédito para uso na próxima compra.')}>Crédito</button><button onClick={()=>s.updateReservation(r.id,'refunded','Valor devolvido ao cliente.')}>Devolvido</button><button onClick={()=>setCancelId(r.id)}>Cancelar</button></div></div>):<p>Nenhuma reserva ativa.</p>}{cancelId&&<div className="cancel-panel"><label>Observação do cancelamento<textarea value={cancelNote} onChange={e=>setCancelNote(e.target.value)} placeholder="Ex.: sabor não ficou pronto, combinamos troca pelo WhatsApp"/></label><button className="primary-button" onClick={cancel}>Confirmar cancelamento</button><button className="secondary-button" onClick={()=>{setCancelId('');setCancelNote('')}}>Voltar</button></div>}</section><section className="soft-card"><Title>Histórico de reservas</Title>{s.reservations.slice(0,8).map(r=><p className="history-line" key={r.id}>{r.customer} · {r.flavor}<small>{r.status}{r.cancelNote?` · ${r.cancelNote}`:''}</small></p>)}</section></AppShell>}
function StampAdjustAdmin(){const s=useStore();const [whatsapp,setWhatsapp]=useState('');const [stamps,setStamps]=useState(0);const [mode,setMode]=useState<'add'|'set'>('set');const [reason,setReason]=useState('Migração do cartão físico');const [message,setMessage]=useState('');const [saving,setSaving]=useState(false);const submit=async()=>{setSaving(true);setMessage('');try{const result=await adjustCustomerStamps({whatsapp,stamps,mode,reason,operatorId:s.currentUserId});setMessage(`${result.customer.name}: cartão ficou com ${result.card.stamps} de ${result.card.stamps_required} carimbos.`);setWhatsapp('');setStamps(0)}catch(e){setMessage(e instanceof Error?e.message:'Não consegui ajustar os carimbos.')}finally{setSaving(false)}};return <AppShell role="admin"><section className="soft-card config-card"><Title>Ajustar Carimbos</Title><p>Use para migrar carimbos do cartão físico. O cliente precisa já ter cadastro beta pelo WhatsApp informado.</p><label>WhatsApp do cliente<input value={whatsapp} onChange={e=>setWhatsapp(e.target.value)} inputMode="tel" placeholder="85999990000"/></label><label>Quantidade atual da cartela física<input type="number" min="0" max="13" value={stamps} onChange={e=>setStamps(+e.target.value)}/></label><div className="choice-grid"><button className={mode==='set'?'active':''} type="button" onClick={()=>setMode('set')}>Definir total</button><button className={mode==='add'?'active':''} type="button" onClick={()=>setMode('add')}>Adicionar</button></div><label>Motivo<input value={reason} onChange={e=>setReason(e.target.value)} placeholder="Ex.: cartão físico apresentado"/></label><Notice>Prefira Definir total para copiar o número atual do cartão físico. Este ajuste fica registrado no histórico de fidelidade do cliente e no log de segurança.</Notice><button className="primary-button" disabled={saving||!whatsapp||stamps<0||reason.trim().length<5} onClick={submit}>{saving?'Salvando...':'Salvar ajuste de carimbos'}</button>{message&&<Notice>{message}</Notice>}</section></AppShell>}
function CustomersAdmin(){const [customers,setCustomers]=useState<CustomerAdminRow[]>([]);const [loading,setLoading]=useState(false);const [error,setError]=useState('');const load=async()=>{setLoading(true);setError('');try{const data=await listCustomers();setCustomers(data.customers)}catch(e){setError(e instanceof Error?e.message:'Não consegui carregar clientes.')}finally{setLoading(false)}};useEffect(()=>{load()},[]);return <AppShell role="admin"><section className="soft-card customers-admin"><Title>Clientes</Title><div className="customer-summary"><b>{customers.length}</b><span>clientes cadastrados</span></div><button className="secondary-button" onClick={load}>{loading?'Atualizando...':'Atualizar lista'}</button>{error&&<Notice>{error}</Notice>}{customers.length?customers.map(customer=><div className="customer-row" key={customer.id}><div><b>{customer.name}</b><span>{customer.whatsapp}</span><small>{customer.instagram||'Instagram não informado'} · Convite: {customer.referred_by_code||'sem código'}</small></div><div><b>{customer.purchase_count}</b><span>compras</span><small>Preferência: {customer.favorite_flavor}</small></div></div>):!loading&&<p>Nenhum cliente cadastrado ainda.</p>}</section></AppShell>}
function Reports(){const s=useStore();const paid=s.sales.filter(v=>v.status==='paid');const gross=paid.reduce((a,v)=>a+v.grossAmount,0);const discounts=paid.reduce((a,v)=>a+(v.discountAmount??0),0);const fees=paid.reduce((a,v)=>a+v.feeAmount,0);const out=s.sales.filter(v=>!['cancelled','declined','expired'].includes(v.status)).reduce((a,v)=>a+v.qty,0);return <AppShell role="admin"><section className="soft-card report-hero"><Title>Relatório do Dia</Title><div className="report-grid"><div><span>Faturamento após descontos</span><b>{money(gross)}</b></div><div><span>Descontos concedidos</span><b>{money(discounts)}</b></div><div><span>Taxas</span><b>{money(fees)}</b></div><div><span>Líquido estimado</span><b>{money(gross-fees)}</b></div><div><span>Fatias restantes</span><b>{Math.max(0,s.available-out)}</b></div><div><span>Gastos do caixa</span><b>{money(s.expenses.reduce((a,v)=>a+v.amount,0))}</b></div><div><span>Saídas sem receita</span><b>{s.sales.filter(v=>noQrPayments.includes(v.payment)).reduce((a,v)=>a+v.qty,0)}</b></div><div><span>Links pendentes</span><b>{s.sales.filter(v=>v.payment==='Mercado Pago Link'&&v.status==='pending').length}</b></div><div><span>Prêmios pendentes</span><b>{s.rewards.filter(v=>v.status==='pendente').length}</b></div></div></section><section className="soft-card payment-report"><Title>Por forma de pagamento</Title>{allPayments.map(p=><p key={p}><span>{p}</span><b>{money(paid.filter(v=>v.payment===p).reduce((a,v)=>a+v.netAmount,0))}</b></p>)}</section><section className="soft-card"><Title>Auditoria</Title>{s.audit.slice(0,8).map(a=><p key={a.id}>{a.action}<small>{a.createdAt}</small></p>)}</section></AppShell>}
function CampaignsAdmin(){const s=useStore();const [cards,setCards]=useState(s.promoCards);const [theme,setTheme]=useState<SeasonalTheme>(s.seasonalTheme);const [ok,setOk]=useState('');const updateCard=(id:string,patch:Partial<PromoCard>)=>setCards(list=>list.map(c=>c.id===id?{...c,...patch}:c));const upload=(id:string,file?:File)=>{if(!file)return;const reader=new FileReader();reader.onload=()=>updateCard(id,{imageUrl:String(reader.result)});reader.readAsDataURL(file)};const addFlash=()=>setCards([{id:uid('FLASH'),day:'relampago',title:'Promoção relâmpago',date:new Date().toISOString().slice(0,10),validUntil:new Date(Date.now()+6*60*60*1000).toISOString(),imageUrl:'/assets/promos/quinta.jpeg',active:true,flash:true,flavors:s.cashFlavors,syrups:s.syrups,notes:''},...cards]);return <AppShell role="admin"><section className="soft-card config-card"><Title>Cards Promocionais</Title><p>Atualize as imagens da semana e deixe cada card expirar no fim do próprio dia.</p><button className="secondary-button" type="button" onClick={addFlash}><Gift/> Criar promoção relâmpago</button>{cards.map(card=><div className="campaign-editor" key={card.id}><img src={card.imageUrl} alt={card.title}/><label>Título<input value={card.title} onChange={e=>updateCard(card.id,{title:e.target.value})}/></label><label>Data<input type="date" value={card.date} onChange={e=>updateCard(card.id,{date:e.target.value})}/></label><label>Expira em<input type="datetime-local" value={card.validUntil.slice(0,16)} onChange={e=>updateCard(card.id,{validUntil:e.target.value})}/></label><label>Imagem<input type="file" accept="image/*" onChange={e=>upload(card.id,e.target.files?.[0])}/></label><label className="check-line"><input type="checkbox" checked={card.active} onChange={e=>updateCard(card.id,{active:e.target.checked})}/> Card ativo para clientes</label><button className="primary-button" onClick={()=>{s.savePromoCard(card);setOk('Card salvo.')}}>Salvar card</button></div>)}{ok&&<Notice>{ok}</Notice>}</section><section className="soft-card config-card"><Title>Tema Sazonal</Title><label>Estilo sazonal<select value={theme.kind} onChange={e=>setTheme({...theme,kind:e.target.value as SeasonalTheme['kind']})}><option value="padrao">Padrão</option><option value="brasil">Brasil / Copa</option><option value="sao-joao">São João</option><option value="namorados">Dia dos Namorados</option></select></label><label className="check-line"><input type="checkbox" checked={theme.active} onChange={e=>setTheme({...theme,active:e.target.checked})}/> Ativar decoração sazonal no app do cliente</label><label>Início<input type="date" value={theme.startsAt} onChange={e=>setTheme({...theme,startsAt:e.target.value})}/></label><label>Fim<input type="date" value={theme.endsAt} onChange={e=>setTheme({...theme,endsAt:e.target.value})}/></label><label>Mensagem<input value={theme.message} onChange={e=>setTheme({...theme,message:e.target.value})} placeholder="Ex.: Garanta sua fatia antes do jogo"/></label><button className="primary-button" onClick={()=>{s.saveTheme(theme);setOk('Tema salvo.')}}>Salvar tema sazonal</button></section></AppShell>}
function PlanningAdmin(){const s=useStore();const [plans,setPlans]=useState(s.plannedProductions);const [ok,setOk]=useState('');const updatePlan=(id:string,patch:Partial<PlannedProduction>)=>setPlans(list=>list.map(p=>p.id===id?{...p,...patch}:p));const updateFlavor=(planId:string,index:number,patch:Partial<FlavorStock>)=>setPlans(list=>list.map(p=>p.id===planId?{...p,flavors:p.flavors.map((f,i)=>i===index?{...f,...patch}:f)}:p));const addFlavor=(planId:string)=>setPlans(list=>list.map(p=>p.id===planId?{...p,flavors:[...p.flavors,{name:'',quantity:0}]}:p));return <AppShell role="admin"><section className="soft-card config-card"><Title>Planejamento da Produção</Title><p>Cadastre a previsão por dia. Na abertura do caixa, use este planejamento como ponto de partida.</p>{plans.map(plan=><div className="campaign-editor" key={plan.id}><label>Dia<input type="date" value={plan.date} onChange={e=>updatePlan(plan.id,{date:e.target.value})}/></label><label>Horário<input value={plan.openingHour} onChange={e=>updatePlan(plan.id,{openingHour:e.target.value})}/></label><div className="form-divider">Sabores previstos</div>{plan.flavors.map((flavor,index)=><div className="flavor-stock-row" key={`${plan.id}-${index}`}><input value={flavor.name} onChange={e=>updateFlavor(plan.id,index,{name:e.target.value})}/><input type="number" min="0" value={flavor.quantity} onChange={e=>updateFlavor(plan.id,index,{quantity:+e.target.value})}/></div>)}<button className="secondary-button" type="button" onClick={()=>addFlavor(plan.id)}><Plus/> Adicionar sabor</button><label>Caldas<input value={plan.syrups.join(', ')} onChange={e=>updatePlan(plan.id,{syrups:e.target.value.split(',').map(v=>v.trim()).filter(Boolean)})}/></label><label>Observações<input value={plan.notes} onChange={e=>updatePlan(plan.id,{notes:e.target.value})}/></label><button className="primary-button" onClick={()=>{s.savePlannedProduction(plan);setOk('Planejamento salvo.')}}>Salvar planejamento</button></div>)}{ok&&<Notice>{ok}</Notice>}</section></AppShell>}
function Admin(){const s=useStore();return <AppShell role="admin"><section className="soft-card admin-hero"><BarChart3/><Title>Painel Gestor</Title><p>{s.cashOpen?'Festival aberto e pronto para vender.':'Abra o festival para iniciar a operação.'}</p></section><div className="report-grid dashboard-grid"><div><span>Faturamento</span><b>{money(s.sales.filter(v=>v.status==='paid').reduce((a,v)=>a+v.grossAmount,0))}</b></div><div><span>Reservas pendentes</span><b>{s.reservations.filter(v=>!['picked_up','cancelled','expired','refunded'].includes(v.status)).length}</b></div><div><span>Prêmios pendentes</span><b>{s.rewards.filter(v=>v.status==='pendente').length}</b></div><div><span>Gastos</span><b>{money(s.expenses.reduce((a,v)=>a+v.amount,0))}</b></div></div><div className="admin-menu"><Link to="/admin/vendas"><ShoppingBag/>Vender<ChevronRight/></Link><Link to="/admin/caixa"><Store/>Abrir/Fechar Caixa<ChevronRight/></Link><Link to="/admin/caixa#gastos"><ReceiptText/>Registrar Gasto<ChevronRight/></Link><Link to="/admin/reservas"><Bell/>Reservas<ChevronRight/></Link><Link to="/admin/clientes"><Users/>Clientes<ChevronRight/></Link><Link to="/admin/carimbos"><BadgeCheck/>Ajustar carimbos<ChevronRight/></Link><Link to="/admin/campanhas"><Gift/>Cards e temas<ChevronRight/></Link><Link to="/admin/planejamento"><CakeSlice/>Planejamento<ChevronRight/></Link><Link to="/admin/relatorios"><BarChart3/>Relatórios<ChevronRight/></Link><Link to="/admin/configuracoes"><Settings/>Configurações<ChevronRight/></Link><Link to="/admin/documentacao"><ExternalLink/>Documentação<ChevronRight/></Link></div></AppShell>}

function Config(){const s=useStore();const tabs=['geral','empresa','mercado','usuarios'] as const;const [searchParams,setSearchParams]=useSearchParams();const requestedTab=searchParams.get('tab');const initialTab=tabs.includes(requestedTab as typeof tabs[number])?requestedTab as typeof tabs[number]:'geral';const [tab,setTabState]=useState<typeof tabs[number]>(initialTab);const setTab=(next:typeof tabs[number])=>{setTabState(next);setSearchParams(next==='geral'?{}:{tab:next})};const [settings,setSettings]=useState(s.settings);const [company,setCompany]=useState(s.company);const [ok,setOk]=useState(false);const [geoMsg,setGeoMsg]=useState('');const numberKeys=['price','cost','stampGoal','pixFee','cardFee','pointFee','linkPixFee','linkCardFee','rewardValidityDays','referralBonusStamps','birthdayDiscountCapPercent'] as const;const companyLabels:Record<string,string>={legalName:'Razão social',tradeName:'Nome fantasia',cnpj:'CNPJ',stateRegistration:'Inscrição estadual',whatsapp:'WhatsApp',instagram:'Instagram',email:'E-mail',address:'Endereço',neighborhood:'Bairro',city:'Cidade',state:'Estado',zipCode:'CEP',reference:'Ponto de referência',placeName:'Nome do local',mapsUrl:'Link do Google Maps',wazeUrl:'Link do Waze',uberUrl:'Link do Uber',openingHours:'Horário de funcionamento',dailyCallout:'Chamada do dia'};const hiddenCompanyFields=new Set(['latitude','longitude']);const useGps=()=>{if(!navigator.geolocation){setGeoMsg('GPS não disponível neste aparelho.');return}setGeoMsg('Buscando posição atual...');navigator.geolocation.getCurrentPosition(pos=>{const latitude=pos.coords.latitude.toFixed(6);const longitude=pos.coords.longitude.toFixed(6);setCompany({...company,latitude,longitude,mapsUrl:`https://www.google.com/maps/search/?api=1&query=${latitude},${longitude}`,wazeUrl:`https://waze.com/ul?ll=${latitude},${longitude}&navigate=yes`});setGeoMsg('Localização salva internamente. Confira os links de rota antes do festival.')},()=>setGeoMsg('Não consegui acessar o GPS. Verifique a permissão de localização do navegador.'),{enableHighAccuracy:true,timeout:12000,maximumAge:60000})};const tabLabels={geral:'Geral',empresa:'Empresa',mercado:'Mercado',usuarios:'Usuários'} as const;return <AppShell role="admin"><div className="config-tabs">{tabs.map(t=><button className={tab===t?'active':''} onClick={()=>setTab(t)} key={t}>{tabLabels[t]}</button>)}</div>{tab==='geral'&&<section className="soft-card config-card"><Title>Configurações Gerais</Title>{numberKeys.map(k=><label key={k}>{({price:'Preço da fatia',cost:'Custo médio da fatia',stampGoal:'Carimbos para prêmio',pixFee:'Taxa Pix (%)',cardFee:'Taxa Cartão (%)',pointFee:'Taxa Mercado Pago Point (%)',linkPixFee:'Taxa Link Pix (%)',linkCardFee:'Taxa Link Cartão (%)',rewardValidityDays:'Validade do prêmio (dias)',referralBonusStamps:'Bônus por indicação',birthdayDiscountCapPercent:'Desconto máximo aniversário (%)'} as const)[k]}<input type="number" value={settings[k]} onChange={e=>setSettings({...settings,[k]:+e.target.value})}/></label>)}<label>Instagram<input value={settings.instagram} onChange={e=>setSettings({...settings,instagram:e.target.value})}/></label><label>WhatsApp<input value={settings.whatsapp} onChange={e=>setSettings({...settings,whatsapp:e.target.value})}/></label><button className="primary-button" onClick={()=>{s.saveSettings(settings);setOk(true)}}>Salvar configurações</button>{ok&&<Notice>Configurações salvas.</Notice>}</section>}{tab==='empresa'&&<section className="soft-card config-card"><Title>Dados da Empresa</Title>{Object.entries(company).filter(([k])=>!hiddenCompanyFields.has(k)).map(([k,v])=><label key={k}>{companyLabels[k]??k}<input value={v} onChange={e=>setCompany({...company,[k]:e.target.value})}/></label>)}<button className="secondary-button" type="button" onClick={useGps}><MapPinned/> Usar GPS deste aparelho</button>{geoMsg&&<Notice>{geoMsg}</Notice>}<button className="primary-button" onClick={()=>{s.saveCompany(company);setOk(true)}}>Salvar dados da empresa</button>{ok&&<Notice>Dados da empresa salvos.</Notice>}</section>}{tab==='mercado'&&<section className="soft-card"><Title>Mercado Pago</Title><Notice>Mock seguro: o Access Token deve existir somente no backend.</Notice>{s.terminals.map(t=><div className="terminal-card" key={t.id}><WalletCards/><div><b>{t.name}</b><span>{t.nickname} · {t.active?'ativo':'inativo'}</span><small>Operador: {s.users.find(u=>u.id===t.operatorId)?.name}</small></div></div>)}</section>}{tab==='usuarios'&&<section className="soft-card"><Title>Usuários Internos</Title>{s.users.map(u=><div className="terminal-card" key={u.id}><UserRound/><div><b>{u.name}</b><span>{u.role} · {u.active?'ativo':'inativo'}</span><small>Terminal: {s.terminals.find(t=>t.id===u.defaultTerminalId)?.name}</small></div></div>)}</section>}</AppShell>}
function MoreAdmin(){const logout=useStore(s=>s.logoutStaff);return <AppShell role="admin"><section className="soft-card admin-menu"><Link to="/admin/clientes"><Users/>Clientes<ChevronRight/></Link><Link to="/admin/carimbos"><BadgeCheck/>Ajustar carimbos<ChevronRight/></Link><Link to="/admin/campanhas"><Gift/>Cards e temas<ChevronRight/></Link><Link to="/admin/planejamento"><CakeSlice/>Planejamento<ChevronRight/></Link><Link to="/admin/configuracoes"><Settings/>Configurações<ChevronRight/></Link><Link to="/admin/configuracoes?tab=usuarios"><Users/>Usuários<ChevronRight/></Link><Link to="/admin/documentacao"><ExternalLink/>Documentação<ChevronRight/></Link><Link to="/equipe" onClick={()=>{clearStaffToken();logout();}}><ExternalLink/>Sair<ChevronRight/></Link></section></AppShell>}
function Documentation(){return <AppShell role="admin"><section className="soft-card documentation-card"><Link className="primary-button back-panel" to="/admin">Voltar ao painel</Link><iframe title="Documentação Adoce Club" src="/documentacao/index.html"/></section></AppShell>}

export default function App(){const client=(node:React.ReactNode)=><RequireClient>{node}</RequireClient>;const staff=(node:React.ReactNode)=><RequireStaff>{node}</RequireStaff>;return <Routes><Route path="*" element={<Navigate to="/cliente" replace/>}/><Route path="/" element={<Navigate to="/cliente" replace/>}/><Route path="/premium-preview" element={<PremiumPreview/>}/><Route path="/premium-cliente" element={<PremiumClient/>}/><Route path="/premium-operacao" element={<PremiumStaff/>}/><Route path="/login" element={<Navigate to="/entrar" replace/>}/><Route path="/cadastro" element={<CustomerRegister/>}/><Route path="/entrar" element={<CustomerLogin/>}/><Route path="/equipe" element={<StaffLogin/>}/><Route path="/cliente" element={client(<ClientHome/>)}/><Route path="/cliente/cartao" element={client(<CardPage/>)}/><Route path="/cliente/familia" element={client(<FamilyPage/>)}/><Route path="/cliente/indicacoes" element={client(<ReferralPage/>)}/><Route path="/cliente/premios" element={client(<Awards/>)}/><Route path="/cliente/perfil" element={client(<Profile/>)}/><Route path="/cliente/mais" element={client(<ClientMore/>)}/><Route path="/cliente/reserva" element={client(<ReservationPage/>)}/><Route path="/cliente/como-chegar" element={client(<LocationPage/>)}/><Route path="/cliente/resgatar/:token" element={client(<Redeem/>)}/><Route path="/vendedor" element={staff(<SellerHome/>)}/><Route path="/vendedor/nova-venda" element={staff(<AppShell role="vendedor"><SalePanel/></AppShell>)}/><Route path="/vendedor/vendas-recentes" element={staff(<AppShell role="vendedor"><RecentSales/></AppShell>)}/><Route path="/vendedor/venda/:id" element={staff(<SaleRoute/>)}/><Route path="/admin" element={staff(<Admin/>)}/><Route path="/admin/vendas" element={staff(<SellerHome/>)}/><Route path="/admin/caixa" element={staff(<Cash/>)}/><Route path="/admin/reservas" element={staff(<ReservationsAdmin/>)}/><Route path="/admin/clientes" element={staff(<CustomersAdmin/>)}/><Route path="/admin/carimbos" element={staff(<StampAdjustAdmin/>)}/><Route path="/admin/campanhas" element={staff(<CampaignsAdmin/>)}/><Route path="/admin/planejamento" element={staff(<PlanningAdmin/>)}/><Route path="/admin/relatorios" element={staff(<Reports/>)}/><Route path="/admin/configuracoes" element={staff(<Config/>)}/><Route path="/admin/documentacao" element={staff(<Documentation/>)}/><Route path="/admin/mais" element={staff(<MoreAdmin/>)}/></Routes>}
